const manifest = { title: 'Synthetic delivery fixture', project: 'SHAR Production', stage: 'delivery', rights_status: 'cleared' };
const stages = new Set(['preproduction', 'production', 'postproduction', 'delivery']);
const releasable = new Set(['cleared', 'licensed', 'synthetic']);
const errors = [];
for (const key of ['title', 'project', 'stage', 'rights_status']) {
  if (typeof manifest[key] !== 'string' || !manifest[key].trim()) errors.push(`${key} is required`);
}
if (manifest.stage && !stages.has(manifest.stage)) errors.push('stage is invalid');
if (manifest.rights_status === 'unknown') errors.push('rights_status=unknown is not releasable');
if (manifest.rights_status && manifest.rights_status !== 'unknown' && !releasable.has(manifest.rights_status)) errors.push('rights_status is invalid');
return [{ json: { publisher: 'SHAR Production', website: 'https://sharprod.com/', releasable: errors.length === 0, errors, declared_manifest: manifest } }];
